#pragma once
// Support header for C++ generated by `forge script --aot` in native mode (docs/aot.md). Not a public API: the
// generated code and this header are versioned together through forge::script::aot::abi_version.
//
// The helpers here are the bytecode VM's instructions (script/src/vm.cpp) and the tree-walker's statements
// (script/src/tree.cpp) written as inline functions over the interpreter's own Interp / Value / heap, so native
// code performs exactly the checks the interpreter performs. The typed fast paths (int and double arithmetic and
// comparisons) take the same decisions as Interp::binary and fall back to it for everything else, including
// every error.
#include "aot.hpp"
#include <cmath>
#include <exception>
#include <limits>

namespace forge::script::aot_rt {

using aot::native_fn;
using aot::unit;
using I64 = std::int64_t;

// ---- lines and steps (VM: Opc::Line; tree: Interp::exec prologue)
inline void ls(Interp& in, int line) { in.line = line; in.step(); }

// ---- locals
inline Obj* moved_obj() { static Obj* const m = moved_sentinel(); return m; }
inline bool moved(const Value& v) { auto* r = std::get_if<Ref<Obj>>(&v); return r && r->get() == moved_obj(); }
inline Env* up(Interp& in, const Ref<Env>& env, int depth) {
    Env* e = env.get();
    for (int d = depth; d > 0 && e; --d) e = e->parent.get();
    if (!e) in.raise("NameError", "bad scope");
    return e;
}
// VM Opc::LoadLocal. The moved-from error names the variable, as the tree-walker's does (Interp::load): the
// interpreter runs a function's first call on the tree-walker, so that is the text `forge script` usually prints.
[[noreturn]] void moved_error(Interp& in, const Node& var);
inline Value ld(Interp& in, const Ref<Env>& env, int depth, int slot, const Node* const* nodes, int var_node) {
    const Value& x = up(in, env, depth)->slots.at(std::size_t(slot));
    if (moved(x)) moved_error(in, *nodes[var_node]);
    return x;
}
// VM Opc::StoreLocal
inline void st(Interp& in, const Ref<Env>& env, int depth, int slot, Value v) {
    up(in, env, depth)->slots.at(std::size_t(slot)) = in.share(v);
}
// VM Opc::ClearLocal
inline void clr(Interp& in, const Ref<Env>& env, int slot) {
    Value dead = std::move(env->slots.at(std::size_t(slot)));
    env->slots[std::size_t(slot)] = Nil{};
    dead = Nil{};
    if (finalizers_pending()) in.run_finalizers();
}
// Tree-walker block scope (Interp::exec_block): block locals are destroyed in reverse order on every exit path.
struct tree_scope {
    const Ref<Env>& env; const Node& n;
    tree_scope(const Ref<Env>& e, const Node& b) : env(e), n(b) {}
    tree_scope(const tree_scope&) = delete; tree_scope& operator=(const tree_scope&) = delete;
    ~tree_scope() {
        if (n.locals.empty() || !env) return;
        for (auto it = n.locals.rbegin(); it != n.locals.rend(); ++it)
            if (std::size_t(*it) < env->slots.size()) { Value dead = std::move(env->slots[std::size_t(*it)]); env->slots[std::size_t(*it)] = Nil{}; }
    }
};

// ---- constants
inline Value dbl(std::uint64_t bits) { double d; std::memcpy(&d, &bits, sizeof d); return d; }
inline double dblv(std::uint64_t bits) { double d; std::memcpy(&d, &bits, sizeof d); return d; }

// ---- operators: the int / double cases of Interp::binary inline, everything else (and every error) in Interp::binary
inline bool both_int(const Value& a, const Value& b) { return a.index() == 2 && b.index() == 2; }
inline bool both_num(const Value& a, const Value& b) { return (a.index() == 2 || a.index() == 3) && (b.index() == 2 || b.index() == 3); }
inline double numv(const Value& v) { return v.index() == 2 ? double(std::get<2>(v)) : std::get<3>(v); }
constexpr I64 imax = std::numeric_limits<I64>::max(), imin = std::numeric_limits<I64>::min();
inline bool add_ok(I64 x, I64 y) { return !((y > 0 && x > imax - y) || (y < 0 && x < imin - y)); }
inline bool sub_ok(I64 x, I64 y) { return !((y < 0 && x > imax + y) || (y > 0 && x < imin + y)); }
inline bool mul_ok(I64 x, I64 y) {
    if (x == 0 || y == 0) return true;
    if ((x == -1 && y == imin) || (y == -1 && x == imin)) return false;
    return !((x > 0 && y > 0 && x > imax / y) || (x < 0 && y < 0 && x < imax / y) || (x > 0 && y < 0 && y < imin / x) || (x < 0 && y > 0 && x < imin / y));
}
inline Value bin(Interp& in, Op op, const Value& a, const Value& b) {
    if (both_int(a, b)) {
        const I64 x = std::get<2>(a), y = std::get<2>(b);
        switch (op) {
        case Op::Add: if (add_ok(x, y)) return x + y; break;
        case Op::Sub: if (sub_ok(x, y)) return x - y; break;
        case Op::Mul: if (mul_ok(x, y)) return x * y; break;
        case Op::Div: if (y != 0 && !(x == imin && y == -1)) return x / y; break;
        case Op::Mod: if (y != 0) return y == -1 ? I64(0) : x % y; break;
        case Op::Eq: return x == y; case Op::Ne: return x != y;
        case Op::Lt: return x < y; case Op::Le: return x <= y; case Op::Gt: return x > y; case Op::Ge: return x >= y;
        case Op::BitAnd: return x & y; case Op::BitOr: return x | y; case Op::BitXor: return x ^ y;
        default: break;
        }
    } else if (both_num(a, b)) {
        const double x = numv(a), y = numv(b);
        switch (op) {
        case Op::Add: return x + y; case Op::Sub: return x - y; case Op::Mul: return x * y; case Op::Div: return x / y;
        case Op::Eq: return x == y; case Op::Ne: return !(x == y);
        case Op::Lt: return x < y; case Op::Le: return x <= y; case Op::Gt: return x > y; case Op::Ge: return x >= y;
        default: break;
        }
    }
    return in.binary(op, a, b);
}

// ---- unboxed ints (locals the code generator proved to hold only ints): Interp::binary's int cases, with its errors
[[noreturn]] void int_error(Interp& in, Op op, I64 x, I64 y);   // raises exactly what Interp::binary(op, x, y) raises
inline I64 iadd(Interp& in, I64 x, I64 y) { if (!add_ok(x, y)) int_error(in, Op::Add, x, y); return x + y; }
inline I64 isub(Interp& in, I64 x, I64 y) { if (!sub_ok(x, y)) int_error(in, Op::Sub, x, y); return x - y; }
inline I64 imul(Interp& in, I64 x, I64 y) { if (!mul_ok(x, y)) int_error(in, Op::Mul, x, y); return x * y; }
inline I64 idiv(Interp& in, I64 x, I64 y) { if (y == 0 || (x == imin && y == -1)) int_error(in, Op::Div, x, y); return x / y; }
inline I64 imod(Interp& in, I64 x, I64 y) { if (y == 0) int_error(in, Op::Mod, x, y); return y == -1 ? I64(0) : x % y; }
inline I64 ishl(Interp& in, I64 x, I64 y) { if (y < 0 || y > 63) int_error(in, Op::Shl, x, y); return I64(std::uint64_t(x) << y); }
inline I64 ishr(Interp& in, I64 x, I64 y) { if (y < 0 || y > 63) int_error(in, Op::Shr, x, y); return x >> y; }
inline I64 ineg(Interp& in, I64 x) { if (x == imin) int_error(in, Op::None, x, 0); return -x; }
// A value that must be an int (the initialiser of a proven-int local whose own type is only known at run time).
I64 need_int(Interp& in, const Value& v, const Node& let);

// ---- statements the VM hands to the tree-walker
[[noreturn]] void throw_value(Interp& in, Value v, int line);                      // NK::Throw
int match_catch(Interp& in, const ScriptError& e, const Node& try_node);           // Interp::run_try: index of the handler kid, 0 = none
void let_check(Interp& in, const Value& v, const Node& let);                       // check_type(v, *let.type, "let " + let.s)
bool same_binding(const Value& x, const Value& y);                                 // for (T& x : c): did the body rebind x?
[[noreturn]] void bad_flow(Interp& in);                                            // break/continue from a delegated statement outside a loop

} // namespace forge::script::aot_rt

// Runner entry for generated code. Returns the process exit status.
namespace forge::script::aot {
int run_native(int argc, char** argv, const unsigned char* payload_bytes, std::size_t payload_size, const unit* units, std::size_t n_units, std::uint32_t abi);
}
